<?php require 'includes/db.php';require 'includes/helpers.php';require_login();ensure_default_categories($pdo);$month=$_GET['month']??date('Y-m');$s=stats($pdo,$month);$cats=categoryTotals($pdo,$month);$bud=budget($pdo,$month);$recent=transactions($pdo,"",[]);$recent=array_slice($recent,0,7);$pct=$bud?min(100,($s['month_expense']/$bud)*100):0;?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Expense Tracker</title><link rel="stylesheet" href="assets/style.css"><script src="https://cdn.jsdelivr.net/npm/chart.js"></script></head><body class="<?=!empty($_SESSION['dark'])?'dark':''?>"><div class="app"><aside class="sidebar"><?php include 'includes/nav.php';?></aside><main class="main"><header class="top"><div><h1>Dashboard</h1><p>Track your money at a glance</p></div><a class="btn primary" href="add.php">+ Add Transaction</a></header>
<section class="kpi-row"><div class="card"><div class="mini">Savings goals</div><div class="big"><?php $gq=$pdo->prepare("SELECT COUNT(*) FROM goals WHERE user_id=?");$gq->execute([user_id()]);echo (int)$gq->fetchColumn();?></div></div><div class="card"><div class="mini">Outstanding loans</div><div class="big"><?php $lq=$pdo->prepare("SELECT COALESCE(SUM(remaining),0) FROM loans WHERE user_id=?");$lq->execute([user_id()]);echo '₹'.money($lq->fetchColumn());?></div></div><div class="card"><div class="mini">Recurring items</div><div class="big"><?php $rq=$pdo->prepare("SELECT COUNT(*) FROM recurring WHERE user_id=? AND active=1");$rq->execute([user_id()]);echo (int)$rq->fetchColumn();?></div></div></section><section class="cards"><div class="card"><div class="label">Balance</div><div class="value">₹<?=money($s['balance'])?></div><div class="muted">Income minus expenses</div></div><div class="card"><div class="label">Total Income</div><div class="value income">₹<?=money($s['income'])?></div><div class="muted">All time</div></div><div class="card"><div class="label">Total Expenses</div><div class="value expense">₹<?=money($s['expense'])?></div><div class="muted">All time</div></div><div class="card"><div class="label">This Month</div><div class="value">₹<?=money($s['month_expense'])?></div><div class="muted"><?=date('F Y',strtotime($month.'-01'))?></div></div></section>
<div class="grid"><section class="panel"><div class="panel-title"><h2>Monthly Budget</h2><a href="budget.php">Manage</a></div><?php if($bud):?><div class="budget-meta"><span>₹<?=money($s['month_expense'])?> spent</span><span>₹<?=money($bud)?> budget</span></div><div class="progress"><span style="width:<?=$pct?>%"></span></div><p class="muted"><?=money(max(0,$bud-$s['month_expense']))?> remaining</p><?php else:?><div class="empty">No budget set for <?=date('F Y',strtotime($month.'-01'))?>.</div><a class="btn primary" href="budget.php">Set Budget</a><?php endif;?></section>
<section class="panel"><div class="panel-title"><h2>Spending by Category</h2><form><input type="month" name="month" value="<?=h($month)?>" onchange="this.form.submit()" style="margin:0;padding:6px"></form></div><div class="chart-box"><?php if($cats):?><canvas id="chart"></canvas><?php else:?><div class="empty">No expenses for this month.</div><?php endif;?></div></section></div>
<section class="panel" style="margin-top:18px"><div class="panel-title"><h2>Recent Transactions</h2><a href="transactions.php">View all</a></div><?php foreach($recent as $r):?><div class="tx"><div class="avatar"><?=h($r['icon'])?></div><div class="txbody"><b><?=h($r['title'])?></b><span><?=h($r['category'])?> · <?=date('d M Y',strtotime($r['date']))?></span></div><div class="txamount <?=$r['type']?>"><?=$r['type']==='income'?'+':'-'?>₹<?=money($r['amount'])?></div></div><?php endforeach;?><?php if(!$recent):?><div class="empty">No transactions yet.</div><?php endif;?></section></main></div>
<script>new Chart(document.getElementById('chart'),{type:'doughnut',data:{labels:<?=json_encode(array_column($cats,'name'))?>,datasets:[{data:<?=json_encode(array_map('floatval',array_column($cats,'total')))?>}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}}});</script></body></html>